() => {
  const items = [...document.querySelectorAll('li[id^="chat-messages-"], li[class*="messageListItem"]')];
  const out = items.map(li => li.innerText.replace(/\n{2,}/g, '\n').trim()).filter(Boolean);
  return { count: out.length, text: out.join('\n---\n').slice(0, 12000) };
}

() => {
  const items = [...document.querySelectorAll('li[id^="chat-messages-"], li[class*="messageListItem"]')];
  return items.map((li,i) => ({
    i,
    links: [...li.querySelectorAll('a')].map(a => a.textContent.trim() + ' => ' + a.href),
    media: [...li.querySelectorAll('video source, video, img[src*="attachments"], a[href*="attachments"]')].map(m => (m.src || m.href))
  }));
}

